# -*- coding: utf-8 -*-
"""The bundled CJK font, embedded as base64 inside the Python code.

Why this file exists: assets/HeliOps_CJK.ttf is shipped as a PyInstaller data
file, which means it is unpacked to a temp folder at runtime. If that
unpacking is blocked (antivirus, folder-access policy, a restricted temp
directory) the game silently falls back to a system font -- and on Windows
that means every Chinese label is a tofu box again.

A Python module is compiled INTO the executable, so the bytes are always
there. game.py writes them to a temp file when the data-file path is not
usable, and loads the font from that.

Source: Noto Sans SC (Google LLC), SIL Open Font License 1.1 -- a subset
containing only the characters the game prints. Full licence: assets/OFL.txt
"""

